mapper.select:
SELECT
FROM file_download_audit
ORDER BY created_at DESC, id DESC LIMIT #{offset}, #{pageSize}

SELECT file_no, SUM(CASE WHEN download_status = 'SUCCESS' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN download_status <> 'SUCCESS' THEN 1 ELSE 0 END) AS failed_count, MAX(CASE WHEN download_status = 'SUCCESS' THEN created_at ELSE NULL END) AS last_success_time, SUBSTRING_INDEX( GROUP_CONCAT(CASE WHEN download_status = 'SUCCESS' THEN client_ip ELSE NULL END ORDER BY created_at DESC), ',', 1 ) AS last_client_ip FROM file_download_audit
AND settle_date = #{settleDate}
AND file_type = #{fileType}
AND file_no = #{fileNo}
AND file_no IS NOT NULL
GROUP BY file_no ORDER BY file_no ASC

SELECT member_id, COUNT(*) AS total_count, SUM(CASE WHEN download_status = 'SUCCESS' THEN 1 ELSE 0 END) AS success_count, SUM(CASE WHEN download_status <> 'SUCCESS' THEN 1 ELSE 0 END) AS failed_count, MAX(created_at) AS last_download_time FROM file_download_audit
AND member_id = #{memberId}
AND created_at >= #{startTime}
AND created_at < #{endTime}
AND member_id IS NOT NULL
GROUP BY member_id ORDER BY total_count DESC

SELECT COUNT(*)
FROM file_download_audit

    AND download_status = #{status}

        AND created_at >= #{startTime}


        AND created_at < #{endTime}

SELECT client_ip AS name, COUNT(*) AS count FROM file_download_audit
AND download_status <> 'SUCCESS' AND client_ip IS NOT NULL AND client_ip <> ''
AND created_at >= #{startTime}
AND created_at < #{endTime}
GROUP BY client_ip ORDER BY count DESC LIMIT #{limit}

SELECT member_id AS name, COUNT(*) AS count FROM file_download_audit
AND download_status <> 'SUCCESS' AND member_id IS NOT NULL AND member_id <> ''
AND created_at >= #{startTime}
AND created_at < #{endTime}
GROUP BY member_id ORDER BY count DESC LIMIT #{limit}
